func quoteSupplierProviderIdentifier(dialect, value string) string {
	if dialect == "mysql" {
		return "`" + value + "`"
	}
	return "\"" + value + "\""
}

func driftSupplierProviderCheck(ddl, dialect, name string) (string, bool) {
	marker := "CONSTRAINT " + quoteSupplierProviderIdentifier(dialect, name) + " CHECK ("
	start := strings.Index(ddl, marker)
	if start < 0 {
		return ddl, false
	}
	end := strings.Index(ddl[start:], "\n")
	if end < 0 {
		end = len(ddl) - start
	}
	line := ddl[start : start+end]
	closing := strings.LastIndex(line, ")")
	if closing < 0 {
		return ddl, false
	}
	driftedLine := line[:closing] + " OR 1 = 1" + line[closing:]
	return strings.Replace(ddl, line, driftedLine, 1), true
}

