func openSupplierProviderDatabase(t *testing.T, dialect, dsn string) *gorm.DB {
	t.Helper()
	dialector, ok := configgormdb.Opens[dialect]
	if !ok {
		t.Fatalf("provider dialect %q is unavailable", dialect)
	}
	db, err := gorm.Open(dialector(dsn), &gorm.Config{
		DisableForeignKeyConstraintWhenMigrating: true,
		TranslateError:                           false,
		Logger:                                   logger.Discard,
	})
	if err != nil {
		t.Fatalf("open %s provider database: %v", dialect, err)
	}
	sqlDB, err := db.DB()
	if err != nil {
		t.Fatalf("obtain %s provider handle: %v", dialect, err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	if err := sqlDB.PingContext(ctx); err != nil {
		cancel()
		_ = sqlDB.Close()
		t.Fatalf("ping %s provider database: %v", dialect, err)
	}
	var databaseName string
	query := "SELECT current_database()"
	if dialect == "mysql" {
		query = "SELECT DATABASE()"
	}
	if err := db.WithContext(ctx).Raw(query).Scan(&databaseName).Error; err != nil {
		cancel()
		_ = sqlDB.Close()
		t.Fatalf("read %s provider database name: %v", dialect, err)
	}
	if databaseName != supplierProviderTestDatabase {
		cancel()
		_ = sqlDB.Close()
		t.Fatalf("refusing destructive %s test outside allowlisted database %q", dialect, supplierProviderTestDatabase)
	}
	t.Cleanup(func() {
		resetSupplierProviderTables(t, db)
		cancel()
		if err := sqlDB.Close(); err != nil {
			t.Errorf("close %s provider database: %v", dialect, err)
		}
	})
	return db.WithContext(ctx)
}

